package com.marmaduke.dps;

/**
 * Everything the damage formula needs for one attack cycle.
 * Levels are the boosted levels RuneLite already reports. Prayer multipliers are separate.
 */
final class CombatInput
{
	int attackLevel;
	int strengthLevel;
	int rangedLevel;
	int magicLevel;

	int stabBonus;
	int slashBonus;
	int crushBonus;
	int magicBonus;
	int rangedBonus;
	int strengthBonus;
	int rangedStrengthBonus;
	/**
	 * Visible magic damage bonus in tenths of a percent. 100 means +10%.
	 */
	int magicDamagePermille;

	CombatStyle combatStyle = CombatStyle.MELEE;
	AttackStance stance = AttackStance.MELEE_AGGRESSIVE;
	MeleeStyle meleeStyle = MeleeStyle.SLASH;
	RangedStyle rangedStyle = RangedStyle.STANDARD;

	int weaponSpeed = 4;
	String weaponName = "";
	String spellName = "";
	int spellMaxHit;
	String spellElement = "";
	String spellbook = "";

	boolean voidMelee;
	boolean voidRanged;
	boolean voidRangedElite;
	boolean voidMagic;
	boolean voidMagicElite;
	boolean salve;
	boolean salveEnchanted;
	boolean salveImbued;
	boolean salveEnchantedImbued;
	boolean blackMask;
	boolean blackMaskImbued;
	boolean onSlayerTask;
	boolean avarice;
	boolean tomeFire;
	boolean tomeWater;
	boolean tomeEarth;
	boolean harmonisedStaff;
	boolean twinflameStaff;
	boolean shadow;
	boolean twistedBow;
	boolean fang;
	boolean crystalBow;
	int crystalPieces;
	boolean arclight;
	boolean emberlight;
	boolean darklight;
	boolean dragonHunterLance;
	boolean dragonHunterCrossbow;
	boolean dragonHunterWand;
	boolean chaosGauntlets;
	int virtusPieces;
	boolean poweredStaff;
	boolean uncharged;

	int meleeAttackPrayer = 100;
	int meleeStrengthPrayer = 100;
	int rangedAttackPrayer = 100;
	int rangedStrengthPrayer = 100;
	int magicAttackPrayer = 100;
	int magicDamagePrayerPermille;

	int npcDefence = 1;
	int npcMagic = 1;
	int npcOffensiveMagic;
	int npcStab;
	int npcSlash;
	int npcCrush;
	int npcMagicDefence;
	int npcLight;
	int npcStandard;
	int npcHeavy;
	int npcFlatArmour;
	boolean undead;
	boolean demon;
	boolean dragon;
	boolean revenant;
	boolean xerician;
	boolean toa;
	boolean magicUsesDefenceLevel;
	String weaknessElement = "";
	int weaknessPercent;

	int meleeAttackBonus()
	{
		switch (meleeStyle)
		{
			case STAB:
				return stabBonus;
			case CRUSH:
				return crushBonus;
			case SLASH:
			default:
				return slashBonus;
		}
	}

	int npcMeleeDefence()
	{
		switch (meleeStyle)
		{
			case STAB:
				return npcStab;
			case CRUSH:
				return npcCrush;
			case SLASH:
			default:
				return npcSlash;
		}
	}

	int npcRangedDefence()
	{
		switch (rangedStyle)
		{
			case LIGHT:
				return npcLight;
			case HEAVY:
				return npcHeavy;
			case STANDARD:
			default:
				return npcStandard;
		}
	}

	CombatInput copy()
	{
		CombatInput copy = new CombatInput();
		copy.attackLevel = attackLevel;
		copy.strengthLevel = strengthLevel;
		copy.rangedLevel = rangedLevel;
		copy.magicLevel = magicLevel;
		copy.stabBonus = stabBonus;
		copy.slashBonus = slashBonus;
		copy.crushBonus = crushBonus;
		copy.magicBonus = magicBonus;
		copy.rangedBonus = rangedBonus;
		copy.strengthBonus = strengthBonus;
		copy.rangedStrengthBonus = rangedStrengthBonus;
		copy.magicDamagePermille = magicDamagePermille;
		copy.combatStyle = combatStyle;
		copy.stance = stance;
		copy.meleeStyle = meleeStyle;
		copy.rangedStyle = rangedStyle;
		copy.weaponSpeed = weaponSpeed;
		copy.weaponName = weaponName;
		copy.spellName = spellName;
		copy.spellMaxHit = spellMaxHit;
		copy.spellElement = spellElement;
		copy.spellbook = spellbook;
		copy.voidMelee = voidMelee;
		copy.voidRanged = voidRanged;
		copy.voidRangedElite = voidRangedElite;
		copy.voidMagic = voidMagic;
		copy.voidMagicElite = voidMagicElite;
		copy.salve = salve;
		copy.salveEnchanted = salveEnchanted;
		copy.salveImbued = salveImbued;
		copy.salveEnchantedImbued = salveEnchantedImbued;
		copy.blackMask = blackMask;
		copy.blackMaskImbued = blackMaskImbued;
		copy.onSlayerTask = onSlayerTask;
		copy.avarice = avarice;
		copy.tomeFire = tomeFire;
		copy.tomeWater = tomeWater;
		copy.tomeEarth = tomeEarth;
		copy.harmonisedStaff = harmonisedStaff;
		copy.twinflameStaff = twinflameStaff;
		copy.shadow = shadow;
		copy.twistedBow = twistedBow;
		copy.fang = fang;
		copy.crystalBow = crystalBow;
		copy.crystalPieces = crystalPieces;
		copy.arclight = arclight;
		copy.emberlight = emberlight;
		copy.darklight = darklight;
		copy.dragonHunterLance = dragonHunterLance;
		copy.dragonHunterCrossbow = dragonHunterCrossbow;
		copy.dragonHunterWand = dragonHunterWand;
		copy.chaosGauntlets = chaosGauntlets;
		copy.virtusPieces = virtusPieces;
		copy.poweredStaff = poweredStaff;
		copy.uncharged = uncharged;
		copy.meleeAttackPrayer = meleeAttackPrayer;
		copy.meleeStrengthPrayer = meleeStrengthPrayer;
		copy.rangedAttackPrayer = rangedAttackPrayer;
		copy.rangedStrengthPrayer = rangedStrengthPrayer;
		copy.magicAttackPrayer = magicAttackPrayer;
		copy.magicDamagePrayerPermille = magicDamagePrayerPermille;
		copy.npcDefence = npcDefence;
		copy.npcMagic = npcMagic;
		copy.npcOffensiveMagic = npcOffensiveMagic;
		copy.npcStab = npcStab;
		copy.npcSlash = npcSlash;
		copy.npcCrush = npcCrush;
		copy.npcMagicDefence = npcMagicDefence;
		copy.npcLight = npcLight;
		copy.npcStandard = npcStandard;
		copy.npcHeavy = npcHeavy;
		copy.npcFlatArmour = npcFlatArmour;
		copy.undead = undead;
		copy.demon = demon;
		copy.dragon = dragon;
		copy.revenant = revenant;
		copy.xerician = xerician;
		copy.toa = toa;
		copy.magicUsesDefenceLevel = magicUsesDefenceLevel;
		copy.weaknessElement = weaknessElement;
		copy.weaknessPercent = weaknessPercent;
		return copy;
	}
}

package com.marmaduke.dps;

/**
 * Player-versus-NPC accuracy and max hit, using the integer formulas published on the
 * OSRS wiki and matched by the maintained Weird Gloop DPS calculator.
 * A successful hit then rolls uniformly from 0 through the max hit. Flat armour is
 * subtracted from each of those rolls.
 */
final class CombatMath
{
	private static final double SECONDS_PER_TICK = 0.6;

	private CombatMath()
	{
	}

	static DpsEstimate estimate(CombatInput in, String targetName, String defenceLabel)
	{
		if (in.uncharged)
		{
			return DpsEstimate.message(targetName, "Weapon is uncharged");
		}
		if (in.combatStyle == CombatStyle.MAGIC && !in.poweredStaff && in.spellMaxHit <= 0
			&& !"Magic Dart".equals(in.spellName))
		{
			return DpsEstimate.message(targetName, "Choose an autocast spell");
		}

		int maxHit = maxHit(in);
		int attackRoll = attackRoll(in);
		int defenceRoll = defenceRoll(in);
		double accuracy = accuracy(in, attackRoll, defenceRoll);
		int speed = attackSpeed(in);
		int flat = in.combatStyle == CombatStyle.MAGIC ? 0 : Math.max(0, in.npcFlatArmour);
		double expected = expectedDamage(accuracy, maxHit, flat);
		double dps = expected / (speed * SECONDS_PER_TICK);

		String note = "";
		String weapon = in.weaponName == null ? "" : in.weaponName.toLowerCase();
		if (weapon.contains("blowpipe"))
		{
			note = "Dart inside the blowpipe is not added";
		}
		else if (weapon.contains("chinchompa"))
		{
			note = "Single-target only; fuse distance is not applied";
		}

		return new DpsEstimate(
			targetName,
			dps,
			maxHit,
			accuracy,
			speed,
			styleLabel(in),
			defenceLabel,
			note);
	}

	static int maxHit(CombatInput in)
	{
		if (in.combatStyle == CombatStyle.MAGIC)
		{
			return magicMaxHit(in);
		}
		if (in.combatStyle == CombatStyle.RANGED)
		{
			return rangedMaxHit(in);
		}
		return meleeMaxHit(in);
	}

	static int attackRoll(CombatInput in)
	{
		if (in.combatStyle == CombatStyle.MAGIC)
		{
			return magicAttackRoll(in);
		}
		if (in.combatStyle == CombatStyle.RANGED)
		{
			return rangedAttackRoll(in);
		}
		return meleeAttackRoll(in);
	}

	static int defenceRoll(CombatInput in)
	{
		if (in.combatStyle == CombatStyle.MAGIC)
		{
			int level = in.magicUsesDefenceLevel ? in.npcDefence : in.npcMagic;
			return (level + 9) * (in.npcMagicDefence + 64);
		}
		int bonus = in.combatStyle == CombatStyle.RANGED ? in.npcRangedDefence() : in.npcMeleeDefence();
		return (in.npcDefence + 9) * (bonus + 64);
	}

	static double accuracy(CombatInput in, int attackRoll, int defenceRoll)
	{
		double hit = normalAccuracy(attackRoll, defenceRoll);
		if (in.fang && in.meleeStyle == MeleeStyle.STAB && in.combatStyle == CombatStyle.MELEE)
		{
			if (in.toa)
			{
				return 1.0 - (1.0 - hit) * (1.0 - hit);
			}
			return fangAccuracy(attackRoll, defenceRoll);
		}
		return hit;
	}

	static double normalAccuracy(int atk, int def)
	{
		if (atk < 0)
		{
			atk = Math.min(0, atk + 2);
		}
		if (def < 0)
		{
			def = Math.min(0, def + 2);
		}
		if (atk >= 0 && def >= 0)
		{
			return atk > def
				? 1.0 - (def + 2.0) / (2.0 * (atk + 1))
				: atk / (2.0 * (def + 1));
		}
		if (atk >= 0)
		{
			return 1.0 - 1.0 / (-def + 1) / (atk + 1);
		}
		return 0;
	}

	static double fangAccuracy(int atk, int def)
	{
		if (atk < 0)
		{
			atk = Math.min(0, atk + 2);
		}
		if (def < 0)
		{
			def = Math.min(0, def + 2);
		}
		if (atk < 0 || def < 0)
		{
			return normalAccuracy(atk, def);
		}
		if (atk > def)
		{
			return 1.0 - (def + 2.0) * (2.0 * def + 3.0) / (atk + 1) / (atk + 1) / 6.0;
		}
		return atk * (4.0 * atk + 5.0) / 6.0 / (atk + 1) / (def + 1);
	}

	static double expectedDamage(double accuracy, int maxHit, int flatReduction)
	{
		if (maxHit < 0)
		{
			maxHit = 0;
		}
		double sum = 0;
		int outcomes = maxHit + 1;
		for (int roll = 0; roll <= maxHit; roll++)
		{
			sum += Math.max(0, roll - flatReduction);
		}
		return accuracy * (sum / outcomes);
	}

	static int attackSpeed(CombatInput in)
	{
		int speed = in.weaponSpeed <= 0 ? 4 : in.weaponSpeed;
		if (in.combatStyle == CombatStyle.RANGED && in.stance == AttackStance.RANGED_RAPID)
		{
			speed -= 1;
		}
		else if (in.combatStyle == CombatStyle.MAGIC && !in.poweredStaff)
		{
			if (in.harmonisedStaff && "standard".equals(in.spellbook))
			{
				speed = 4;
			}
			else if (in.twinflameStaff)
			{
				speed = 6;
			}
			else
			{
				speed = 5;
			}
		}
		return Math.max(1, speed);
	}

	static int tbowScale(int current, int magicLevel, boolean accuracy)
	{
		int factor = accuracy ? 10 : 14;
		int base = accuracy ? 140 : 250;
		int clamp = accuracy ? 140 : 250;
		int t2 = (3 * magicLevel - factor) / 100;
		int inner = (3 * magicLevel / 10) - (10 * factor);
		int t3 = (inner * inner) / 100;
		int bonus = Math.max(0, Math.min(clamp, base + t2 - t3));
		return current * bonus / 100;
	}

	private static int meleeMaxHit(CombatInput in)
	{
		int effective = in.strengthLevel * in.meleeStrengthPrayer / 100;
		if (in.stance == AttackStance.MELEE_AGGRESSIVE)
		{
			effective += 3;
		}
		else if (in.stance == AttackStance.MELEE_CONTROLLED)
		{
			effective += 1;
		}
		effective += 8;
		if (in.voidMelee)
		{
			effective = effective * 11 / 10;
		}
		int max = (effective * (in.strengthBonus + 64) + 320) / 640;
		max = applyMeleeGearBonus(in, max);
		if ((in.arclight || in.emberlight) && in.demon)
		{
			max += max * 70 / 100;
		}
		else if (in.darklight && in.demon)
		{
			max += max * 60 / 100;
		}
		if (in.dragon && in.dragonHunterLance)
		{
			max = max * 6 / 5;
		}
		else if (in.dragon && in.dragonHunterWand)
		{
			max = max * 7 / 5;
		}
		return Math.max(0, max);
	}

	private static int rangedMaxHit(CombatInput in)
	{
		int effective = in.rangedLevel * in.rangedStrengthPrayer / 100;
		if (in.stance == AttackStance.RANGED_ACCURATE)
		{
			effective += 3;
		}
		effective += 8;
		if (in.voidRangedElite)
		{
			effective = effective * 9 / 8;
		}
		else if (in.voidRanged)
		{
			effective = effective * 11 / 10;
		}
		int max = (effective * (in.rangedStrengthBonus + 64) + 320) / 640;
		if (in.crystalBow && in.crystalPieces > 0)
		{
			max = max * (40 + in.crystalPieces) / 40;
		}
		max = applyRangedGearBonus(in, max);
		if (in.twistedBow)
		{
			max = tbowScale(max, tbowMagic(in), false);
		}
		if (in.dragon && in.dragonHunterCrossbow)
		{
			max = max * 5 / 4;
		}
		return Math.max(0, max);
	}

	private static int magicMaxHit(CombatInput in)
	{
		int base = poweredStaffBase(in);
		if (base < 0)
		{
			if ("Magic Dart".equals(in.spellName))
			{
				base = in.blackMaskImbued && in.onSlayerTask
					? 13 + in.magicLevel / 6
					: 10 + in.magicLevel / 10;
			}
			else
			{
				base = Math.max(0, in.spellMaxHit);
			}
			if (in.chaosGauntlets && in.spellName != null && in.spellName.toLowerCase().contains("bolt"))
			{
				base += 3;
			}
		}
		if (base <= 0)
		{
			return 0;
		}

		int bonus = in.magicDamagePermille;
		if (in.shadow)
		{
			int factor = in.toa ? 4 : 3;
			bonus = Math.min(1000, bonus * factor);
		}
		if ("ancient".equals(in.spellbook) && !in.poweredStaff)
		{
			bonus += 30 * in.virtusPieces;
		}
		if (in.voidMagicElite)
		{
			bonus += 50;
		}
		if (in.avarice && in.revenant)
		{
			bonus += 200;
		}
		else if (in.undead && in.salveEnchantedImbued)
		{
			bonus += 200;
		}
		else if (in.undead && in.salveImbued)
		{
			bonus += 150;
		}
		bonus += in.magicDamagePrayerPermille;

		int max = base + base * bonus / 1000;
		boolean salve = in.undead && (in.salveImbued || in.salveEnchantedImbued);
		if (!salve && !(in.avarice && in.revenant) && in.blackMaskImbued && in.onSlayerTask)
		{
			max = max * 23 / 20;
		}
		if (in.dragon)
		{
			if (in.dragonHunterLance)
			{
				max = max * 6 / 5;
			}
			else if (in.dragonHunterWand)
			{
				max = max * 7 / 5;
			}
			else if (in.dragonHunterCrossbow)
			{
				max = max * 5 / 4;
			}
		}
		if (in.weaknessElement != null && in.weaknessElement.equals(in.spellElement) && in.weaknessPercent > 0)
		{
			max += base * in.weaknessPercent / 100;
		}
		if (tomeMatches(in))
		{
			max = max * 11 / 10;
		}
		return Math.max(0, max);
	}

	private static int poweredStaffBase(CombatInput in)
	{
		if (!in.poweredStaff)
		{
			return -1;
		}
		String name = in.weaponName == null ? "" : in.weaponName.toLowerCase();
		int magic = in.magicLevel;
		if (name.contains("trident of the seas"))
		{
			return Math.max(1, magic / 3 - 5);
		}
		if (name.contains("trident of the swamp"))
		{
			return Math.max(1, magic / 3 - 2);
		}
		if (name.contains("sanguinesti"))
		{
			return Math.max(1, magic / 3);
		}
		if (name.contains("tumeken"))
		{
			return Math.max(1, magic / 3 + 1);
		}
		if (name.contains("thammaron"))
		{
			return Math.max(1, magic / 3 - 8);
		}
		if (name.contains("accursed"))
		{
			return Math.max(1, magic / 3 - 6);
		}
		if (name.contains("eye of ayak"))
		{
			return Math.max(1, magic / 3 - 6);
		}
		if (name.contains("warped sceptre"))
		{
			return Math.max(1, (8 * magic + 96) / 37);
		}
		if (name.contains("bone staff"))
		{
			return Math.max(1, magic / 3 - 5) + 10;
		}
		if (name.contains("dawnbringer"))
		{
			return Math.max(1, magic / 3 - 2);
		}
		if (name.contains("starter staff"))
		{
			return 8;
		}
		return -1;
	}

	private static int meleeAttackRoll(CombatInput in)
	{
		int effective = in.attackLevel * in.meleeAttackPrayer / 100;
		if (in.stance == AttackStance.MELEE_ACCURATE)
		{
			effective += 3;
		}
		else if (in.stance == AttackStance.MELEE_CONTROLLED)
		{
			effective += 1;
		}
		effective += 8;
		if (in.voidMelee)
		{
			effective = effective * 11 / 10;
		}
		int roll = effective * (in.meleeAttackBonus() + 64);
		roll = applyMeleeGearBonus(in, roll);
		if ((in.arclight || in.emberlight) && in.demon)
		{
			roll += roll * 70 / 100;
		}
		else if (in.darklight && in.demon)
		{
			roll += roll * 60 / 100;
		}
		if (in.dragon && in.dragonHunterLance)
		{
			roll = roll * 6 / 5;
		}
		else if (in.dragon && in.dragonHunterWand)
		{
			roll = roll * 7 / 4;
		}
		return roll;
	}

	private static int rangedAttackRoll(CombatInput in)
	{
		int effective = in.rangedLevel * in.rangedAttackPrayer / 100;
		if (in.stance == AttackStance.RANGED_ACCURATE)
		{
			effective += 3;
		}
		effective += 8;
		if (in.voidRangedElite)
		{
			effective = effective * 9 / 8;
		}
		else if (in.voidRanged)
		{
			effective = effective * 11 / 10;
		}
		int roll = effective * (in.rangedBonus + 64);
		roll = applyRangedGearBonus(in, roll);
		if (in.twistedBow)
		{
			roll = tbowScale(roll, tbowMagic(in), true);
		}
		if (in.dragon && in.dragonHunterCrossbow)
		{
			roll = roll * 13 / 10;
		}
		return roll;
	}

	private static int magicAttackRoll(CombatInput in)
	{
		int effective = in.magicLevel * in.magicAttackPrayer / 100;
		if (in.stance == AttackStance.MAGIC_ACCURATE)
		{
			effective += 2;
		}
		effective += 9;
		if (in.voidMagic || in.voidMagicElite)
		{
			effective = effective * 29 / 20;
		}
		int magicBonus = in.magicBonus;
		if (in.shadow)
		{
			magicBonus *= in.toa ? 4 : 3;
		}
		int base = effective * (magicBonus + 64);
		int roll = base;
		if (in.avarice && in.revenant)
		{
			roll = roll * 120 / 100;
		}
		else if (in.undead && in.salveEnchantedImbued)
		{
			roll = roll * 120 / 100;
		}
		else if (in.undead && in.salveImbued)
		{
			roll = roll * 115 / 100;
		}
		else if (in.blackMaskImbued && in.onSlayerTask)
		{
			roll = roll * 23 / 20;
		}
		if (in.dragon)
		{
			if (in.dragonHunterCrossbow)
			{
				roll = roll * 13 / 10;
			}
			else if (in.dragonHunterLance)
			{
				roll = roll * 6 / 5;
			}
			else if (in.dragonHunterWand)
			{
				roll = roll * 7 / 4;
			}
		}
		if (in.weaknessElement != null && in.weaknessElement.equals(in.spellElement) && in.weaknessPercent > 0)
		{
			roll += base * in.weaknessPercent / 100;
		}
		if (in.tomeWater && "water".equals(in.spellElement))
		{
			roll = roll * 6 / 5;
		}
		return roll;
	}

	private static int applyMeleeGearBonus(CombatInput in, int value)
	{
		if (in.avarice && in.revenant)
		{
			return value * 6 / 5;
		}
		if (in.undead && (in.salveEnchanted || in.salveEnchantedImbued))
		{
			return value * 6 / 5;
		}
		if (in.undead && (in.salve || in.salveImbued))
		{
			return value * 7 / 6;
		}
		if (in.onSlayerTask && (in.blackMask || in.blackMaskImbued))
		{
			return value * 7 / 6;
		}
		return value;
	}

	private static int applyRangedGearBonus(CombatInput in, int value)
	{
		if (in.avarice && in.revenant)
		{
			return value * 6 / 5;
		}
		if (in.undead && in.salveEnchantedImbued)
		{
			return value * 6 / 5;
		}
		if (in.undead && in.salveImbued)
		{
			return value * 7 / 6;
		}
		if (in.onSlayerTask && in.blackMaskImbued)
		{
			return value * 23 / 20;
		}
		return value;
	}

	private static int tbowMagic(CombatInput in)
	{
		int cap = in.xerician ? 350 : 250;
		return Math.min(cap, Math.max(in.npcMagic, in.npcOffensiveMagic));
	}

	private static boolean tomeMatches(CombatInput in)
	{
		return (in.tomeFire && "fire".equals(in.spellElement))
			|| (in.tomeWater && "water".equals(in.spellElement))
			|| (in.tomeEarth && "earth".equals(in.spellElement));
	}

	private static String styleLabel(CombatInput in)
	{
		if (in.combatStyle == CombatStyle.MAGIC)
		{
			String spell = in.spellName != null && !in.spellName.isEmpty() ? in.spellName : "Magic";
			if (in.stance == AttackStance.MAGIC_DEFENSIVE)
			{
				return spell + " defensive";
			}
			if (in.stance == AttackStance.MAGIC_AUTOCAST)
			{
				return spell + " autocast";
			}
			if (in.stance == AttackStance.MAGIC_ACCURATE)
			{
				return spell + " accurate";
			}
			return spell;
		}
		if (in.combatStyle == CombatStyle.RANGED)
		{
			String stance = rangedStanceLabel(in.stance);
			if (in.rangedStyle == RangedStyle.LIGHT)
			{
				return stance + " (light)";
			}
			if (in.rangedStyle == RangedStyle.HEAVY)
			{
				return stance + " (heavy)";
			}
			return stance;
		}
		String melee;
		switch (in.meleeStyle)
		{
			case STAB:
				melee = "Stab";
				break;
			case CRUSH:
				melee = "Crush";
				break;
			case SLASH:
			default:
				melee = "Slash";
				break;
		}
		return melee + " " + meleeStanceLabel(in.stance);
	}

	private static String rangedStanceLabel(AttackStance stance)
	{
		if (stance == AttackStance.RANGED_RAPID)
		{
			return "Rapid";
		}
		if (stance == AttackStance.RANGED_LONG)
		{
			return "Longrange";
		}
		return "Accurate";
	}

	private static String meleeStanceLabel(AttackStance stance)
	{
		if (stance == AttackStance.MELEE_AGGRESSIVE)
		{
			return "aggressive";
		}
		if (stance == AttackStance.MELEE_CONTROLLED)
		{
			return "controlled";
		}
		if (stance == AttackStance.MELEE_DEFENSIVE)
		{
			return "defensive";
		}
		if (stance == AttackStance.MAGIC_AUTOCAST)
		{
			return "autocast";
		}
		if (stance == AttackStance.MAGIC_DEFENSIVE)
		{
			return "defensive cast";
		}
		return "accurate";
	}
}

package com.marmaduke.dps;

/**
 * Defence, magic, and the other combat levels of one NPC after reductions this client has seen.
 * Percent drains use integer truncation: {@code level - level * percent / 100}.
 */
final class DefenceModel
{
	private static final int VULNERABILITY_TICKS = 100;

	int defence;
	int magic;
	int attack;
	int strength;
	int ranged;
	private final int baseDefence;
	private final int baseMagic;

	private int dwhHits;
	private int elderHits;
	private int bgsDamage;
	private int arclightHits;
	private int emberlightHits;
	private int darklightHits;
	private boolean accursed;
	private int tonalzticsPercent;
	private int vulnLeft;
	private int vulnAmount;
	private boolean vulnFifteen;

	DefenceModel(NpcCombatStats stats)
	{
		this.defence = stats.def;
		this.magic = stats.magic;
		this.attack = stats.atk;
		this.strength = stats.str;
		this.ranged = stats.ranged;
		this.baseDefence = stats.def;
		this.baseMagic = stats.magic;
	}

	void applyDragonWarhammer(boolean tektonMiss)
	{
		int percent = tektonMiss ? 5 : 30;
		defence = reducePercent(defence, percent);
		if (tektonMiss)
		{
			return;
		}
		dwhHits++;
	}

	void applyElderMaul(boolean tektonMiss)
	{
		defence = reducePercent(defence, tektonMiss ? 5 : 35);
		if (!tektonMiss)
		{
			elderHits++;
		}
	}

	void applyBandosGodsword(int damage)
	{
		if (damage <= 0)
		{
			return;
		}
		bgsDamage += damage;
		int left = damage;
		left = drainFlat(Stat.DEFENCE, left);
		left = drainFlat(Stat.STRENGTH, left);
		left = drainFlat(Stat.ATTACK, left);
		left = drainFlat(Stat.MAGIC, left);
		drainFlat(Stat.RANGED, left);
	}

	/**
	 * Accursed sceptre drains 15% of current Defence and Magic, and cannot push either
	 * below 85% of the level the NPC had when it was first tracked.
	 */
	void applyAccursedSceptre()
	{
		accursed = true;
		defence = capPercent(defence, baseDefence, 15);
		magic = capPercent(magic, baseMagic, 15);
	}

	void applyArclight()
	{
		arclightHits++;
		attack = reducePercent(attack, 5);
		strength = reducePercent(strength, 5);
		defence = reducePercent(defence, 5);
	}

	void applyDarklight()
	{
		darklightHits++;
		attack = reducePercent(attack, 5);
		strength = reducePercent(strength, 5);
		defence = reducePercent(defence, 5);
	}

	void applyEmberlight()
	{
		emberlightHits++;
		attack = reducePercent(attack, 5);
		strength = reducePercent(strength, 5);
		defence = reducePercent(defence, 5);
		magic = reducePercent(magic, 5);
		ranged = reducePercent(ranged, 5);
	}

	/**
	 * @param damagingHits number of tonalztics hitsplats above 0. Two damaging hits drain
	 *                     20% of the target's Magic level from Defence; one drains 10%.
	 */
	void applyTonalztics(int damagingHits)
	{
		int percent = damagingHits >= 2 ? 20 : damagingHits == 1 ? 10 : 0;
		if (percent == 0)
		{
			return;
		}
		tonalzticsPercent += percent;
		int drain = magic * percent / 100;
		defence = Math.max(0, defence - drain);
	}

	void applyVulnerability(int percent)
	{
		if (vulnLeft > 0)
		{
			vulnLeft = VULNERABILITY_TICKS;
			return;
		}
		vulnAmount = defence * percent / 100;
		defence = Math.max(0, defence - vulnAmount);
		vulnLeft = VULNERABILITY_TICKS;
		vulnFifteen = percent >= 15;
	}

	void tick()
	{
		if (vulnLeft <= 0)
		{
			return;
		}
		vulnLeft--;
		if (vulnLeft == 0)
		{
			defence += vulnAmount;
			vulnAmount = 0;
		}
	}

	/**
	 * Overlay text for defence. Unreduced levels are the current number. A reduced level is the
	 * starting defence, a hyphen, and the points removed: 90 reduced by 30 is {@code 90-30}.
	 */
	String overlayDefence()
	{
		if (defence < baseDefence)
		{
			return baseDefence + "-" + (baseDefence - defence);
		}
		return Integer.toString(defence);
	}

	String describe()
	{
		StringBuilder builder = new StringBuilder();
		append(builder, dwhHits, "DWH");
		append(builder, elderHits, "Elder maul");
		if (bgsDamage > 0)
		{
			appendRaw(builder, "BGS " + bgsDamage);
		}
		if (accursed)
		{
			appendRaw(builder, "Accursed");
		}
		append(builder, arclightHits, "Arclight");
		append(builder, darklightHits, "Darklight");
		append(builder, emberlightHits, "Emberlight");
		if (tonalzticsPercent > 0)
		{
			appendRaw(builder, "Tonalztics " + tonalzticsPercent + "%");
		}
		if (vulnLeft > 0)
		{
			appendRaw(builder, vulnFifteen ? "Vuln 15%" : "Vuln");
		}
		return builder.toString();
	}

	private static void append(StringBuilder builder, int hits, String label)
	{
		if (hits <= 0)
		{
			return;
		}
		appendRaw(builder, hits == 1 ? label : label + " x" + hits);
	}

	private static void appendRaw(StringBuilder builder, String text)
	{
		if (builder.length() > 0)
		{
			builder.append(", ");
		}
		builder.append(text);
	}

	private int drainFlat(Stat stat, int amount)
	{
		if (amount <= 0)
		{
			return 0;
		}
		int current = get(stat);
		int taken = Math.min(current, amount);
		set(stat, current - taken);
		return amount - taken;
	}

	private static int reducePercent(int level, int percent)
	{
		return Math.max(0, level - level * percent / 100);
	}

	private static int capPercent(int current, int base, int percent)
	{
		int floor = base * (100 - percent) / 100;
		int drained = current - current * percent / 100;
		if (drained < floor)
		{
			drained = floor;
		}
		return Math.min(current, Math.max(0, drained));
	}

	private int get(Stat stat)
	{
		switch (stat)
		{
			case DEFENCE:
				return defence;
			case MAGIC:
				return magic;
			case ATTACK:
				return attack;
			case STRENGTH:
				return strength;
			case RANGED:
			default:
				return ranged;
		}
	}

	private void set(Stat stat, int value)
	{
		switch (stat)
		{
			case DEFENCE:
				defence = value;
				break;
			case MAGIC:
				magic = value;
				break;
			case ATTACK:
				attack = value;
				break;
			case STRENGTH:
				strength = value;
				break;
			case RANGED:
			default:
				ranged = value;
				break;
		}
	}

	private enum Stat
	{
		DEFENCE,
		STRENGTH,
		ATTACK,
		MAGIC,
		RANGED
	}
}

