package com.marmaduke.dps;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

final class NpcStatsIndex
{
	private final Map<Integer, NpcCombatStats> byId;

	private NpcStatsIndex(Map<Integer, NpcCombatStats> byId)
	{
		this.byId = byId;
	}

	static NpcStatsIndex empty()
	{
		return new NpcStatsIndex(Collections.emptyMap());
	}

	static NpcStatsIndex load(Gson gson, InputStream in)
	{
		if (in == null)
		{
			return new NpcStatsIndex(Collections.emptyMap());
		}
		JsonElement element;
		try (InputStreamReader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			element = new JsonParser().parse(reader);
		}
		catch (IOException ex)
		{
			return new NpcStatsIndex(Collections.emptyMap());
		}
		Map<Integer, NpcCombatStats> byId = new HashMap<Integer, NpcCombatStats>();
		if (element != null && element.isJsonArray())
		{
			for (JsonElement row : element.getAsJsonArray())
			{
				NpcCombatStats stat = gson.fromJson(row, NpcCombatStats.class);
				if (stat != null && !byId.containsKey(stat.id))
				{
					byId.put(stat.id, stat);
				}
			}
		}
		return new NpcStatsIndex(byId);
	}

	NpcCombatStats get(int id)
	{
		return byId.get(id);
	}

	int size()
	{
		return byId.size();
	}
}

package com.marmaduke.dps;

import java.awt.FontMetrics;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Breaks overlay copy onto lines that fit a pixel width, including words longer than that width.
 */
final class OverlayText
{
	private OverlayText()
	{
	}

	static List<String> wrap(FontMetrics metrics, String text, int maxWidth)
	{
		if (text == null)
		{
			return Collections.emptyList();
		}
		String trimmed = text.trim();
		if (trimmed.isEmpty())
		{
			return Collections.emptyList();
		}
		int limit = Math.max(maxWidth, 1);
		List<String> lines = new ArrayList<String>();
		StringBuilder current = new StringBuilder();
		String[] words = trimmed.split("\\s+");
		for (int i = 0; i < words.length; i++)
		{
			List<String> pieces = breakWord(metrics, words[i], limit);
			for (int p = 0; p < pieces.size(); p++)
			{
				String piece = pieces.get(p);
				if (current.length() == 0)
				{
					current.append(piece);
					continue;
				}
				String candidate = current.toString() + " " + piece;
				if (metrics.stringWidth(candidate) <= limit)
				{
					current.append(' ').append(piece);
				}
				else
				{
					lines.add(current.toString());
					current.setLength(0);
					current.append(piece);
				}
			}
		}
		if (current.length() > 0)
		{
			lines.add(current.toString());
		}
		return lines;
	}

	static String clip(FontMetrics metrics, String text, int maxWidth)
	{
		if (text == null || text.isEmpty())
		{
			return "";
		}
		if (maxWidth <= 0 || metrics.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		String ellipsis = "...";
		if (metrics.stringWidth(ellipsis) >= maxWidth)
		{
			return ellipsis;
		}
		int end = text.length();
		while (end > 0 && metrics.stringWidth(text.substring(0, end) + ellipsis) > maxWidth)
		{
			end--;
		}
		return text.substring(0, end) + ellipsis;
	}

	private static List<String> breakWord(FontMetrics metrics, String word, int limit)
	{
		List<String> pieces = new ArrayList<String>();
		int start = 0;
		while (start < word.length())
		{
			int end = start + 1;
			while (end < word.length() && metrics.stringWidth(word.substring(start, end + 1)) <= limit)
			{
				end++;
			}
			pieces.add(word.substring(start, end));
			start = end;
		}
		return pieces;
	}
}

package com.marmaduke.dps;

import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ParamID;
import net.runelite.api.Skill;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

/**
 * Reads worn gear, prayers, boosted stats, and the selected attack style from the client.
 */
final class PlayerGear
{
	private PlayerGear()
	{
	}

	static CombatInput build(Client client, ItemManager itemManager, boolean onSlayerTask, NpcCombatStats npc, DefenceModel defence)
	{
		CombatInput in = new CombatInput();
		in.attackLevel = client.getBoostedSkillLevel(Skill.ATTACK);
		in.strengthLevel = client.getBoostedSkillLevel(Skill.STRENGTH);
		in.rangedLevel = client.getBoostedSkillLevel(Skill.RANGED);
		in.magicLevel = client.getBoostedSkillLevel(Skill.MAGIC);
		in.onSlayerTask = onSlayerTask;

		String weaponName = "";
		String headName = "";
		String bodyName = "";
		String legsName = "";
		String glovesName = "";
		ItemEquipmentStats weaponEquipment = null;
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment != null)
		{
			for (EquipmentInventorySlot slot : EquipmentInventorySlot.values())
			{
				Item item = equipment.getItem(slot.getSlotIdx());
				if (item == null || item.getId() < 0)
				{
					continue;
				}
				String name = itemName(itemManager, item.getId());
				if (slot == EquipmentInventorySlot.HEAD)
				{
					headName = name;
				}
				else if (slot == EquipmentInventorySlot.BODY)
				{
					bodyName = name;
				}
				else if (slot == EquipmentInventorySlot.LEGS)
				{
					legsName = name;
				}
				else if (slot == EquipmentInventorySlot.GLOVES)
				{
					glovesName = name;
				}
				ItemStats stats = itemManager.getItemStats(item.getId());
				if (stats != null && stats.getEquipment() != null)
				{
					addEquipment(in, stats.getEquipment());
				}
				if (slot == EquipmentInventorySlot.WEAPON)
				{
					weaponName = name;
					if (stats != null)
					{
						weaponEquipment = stats.getEquipment();
					}
				}
				applyNamedGear(in, slot, name);
			}
		}
		finishVoid(in, headName, bodyName, legsName, glovesName);

		in.weaponName = weaponName;
		if (weaponEquipment != null && weaponEquipment.getAspeed() > 0)
		{
			in.weaponSpeed = weaponEquipment.getAspeed();
		}
		in.poweredStaff = isPoweredStaff(weaponName);
		in.uncharged = isUncharged(weaponName);
		in.meleeStyle = meleeStyle(weaponEquipment, client);

		StyleSelection style = readStyle(client);
		in.stance = stanceFrom(style, in.poweredStaff);
		if (in.poweredStaff)
		{
			in.combatStyle = CombatStyle.MAGIC;
			if (in.stance == AttackStance.RANGED_LONG
				|| in.stance == AttackStance.MELEE_DEFENSIVE
				|| in.stance == AttackStance.MAGIC_DEFENSIVE)
			{
				in.stance = AttackStance.MAGIC_DEFENSIVE;
			}
			else
			{
				in.stance = AttackStance.MAGIC_ACCURATE;
			}
		}
		else if (in.stance == AttackStance.RANGED_ACCURATE
			|| in.stance == AttackStance.RANGED_RAPID
			|| in.stance == AttackStance.RANGED_LONG)
		{
			in.combatStyle = CombatStyle.RANGED;
		}
		else if (in.stance == AttackStance.MAGIC_ACCURATE
			|| in.stance == AttackStance.MAGIC_AUTOCAST
			|| in.stance == AttackStance.MAGIC_DEFENSIVE)
		{
			in.combatStyle = CombatStyle.MAGIC;
		}
		else
		{
			in.combatStyle = CombatStyle.MELEE;
		}

		in.rangedStyle = rangedStyle(weaponName);
		applyPrayers(client, in);

		if (in.combatStyle == CombatStyle.MAGIC && !in.poweredStaff)
		{
			SpellTable spell = SpellTable.fromAutocast(client.getVarbitValue(VarbitID.AUTOCAST_SPELL));
			if (spell != null)
			{
				in.spellName = spell.name;
				in.spellMaxHit = spell.maxHit;
				in.spellElement = spell.element;
				in.spellbook = spell.spellbook;
			}
		}

		if (npc != null)
		{
			in.npcDefence = defence != null ? defence.defence : npc.def;
			in.npcMagic = defence != null ? defence.magic : npc.magic;
			in.npcOffensiveMagic = npc.omagic;
			in.npcStab = npc.stab;
			in.npcSlash = npc.slash;
			in.npcCrush = npc.crush;
			in.npcMagicDefence = npc.mage;
			in.npcLight = npc.light;
			in.npcStandard = npc.std;
			in.npcHeavy = npc.heavy;
			in.npcFlatArmour = npc.flat;
			in.undead = npc.has("undead") || npc.has("vampyre1") || npc.has("vampyre2") || npc.has("vampyre3");
			in.demon = npc.has("demon");
			in.dragon = npc.has("dragon");
			in.xerician = npc.has("xerician");
			in.revenant = npc.name != null && npc.name.startsWith("Revenant");
			in.toa = npc.toa;
			in.magicUsesDefenceLevel = npc.mageUsesDef;
			in.weaknessElement = npc.weak == null ? "" : npc.weak;
			in.weaknessPercent = npc.weakPct;
		}
		return in;
	}

	private static void addEquipment(CombatInput in, ItemEquipmentStats equipment)
	{
		in.stabBonus += equipment.getAstab();
		in.slashBonus += equipment.getAslash();
		in.crushBonus += equipment.getAcrush();
		in.magicBonus += equipment.getAmagic();
		in.rangedBonus += equipment.getArange();
		in.strengthBonus += equipment.getStr();
		in.rangedStrengthBonus += equipment.getRstr();
		in.magicDamagePermille += Math.round(equipment.getMdmg() * 10f);
	}

	private static void applyNamedGear(CombatInput in, EquipmentInventorySlot slot, String name)
	{
		String lower = name.toLowerCase();
		if (slot == EquipmentInventorySlot.HEAD)
		{
			if (lower.contains("crystal helm"))
			{
				in.crystalPieces += 1;
			}
			if (lower.contains("virtus"))
			{
				in.virtusPieces++;
			}
		}
		else if (slot == EquipmentInventorySlot.BODY)
		{
			if (lower.contains("crystal body"))
			{
				in.crystalPieces += 3;
			}
			if (lower.contains("virtus"))
			{
				in.virtusPieces++;
			}
		}
		else if (slot == EquipmentInventorySlot.LEGS)
		{
			if (lower.contains("crystal legs"))
			{
				in.crystalPieces += 2;
			}
			if (lower.contains("virtus"))
			{
				in.virtusPieces++;
			}
		}
		else if (slot == EquipmentInventorySlot.GLOVES)
		{
			if (lower.contains("chaos gauntlets"))
			{
				in.chaosGauntlets = true;
			}
		}
		else if (slot == EquipmentInventorySlot.AMULET)
		{
			if (lower.contains("amulet of avarice"))
			{
				in.avarice = true;
			}
			if (lower.contains("salve amulet(ei)") || lower.contains("salve amulet (ei)"))
			{
				in.salveEnchantedImbued = true;
			}
			else if (lower.contains("salve amulet(e)") || lower.contains("salve amulet (e)"))
			{
				in.salveEnchanted = true;
			}
			else if (lower.contains("salve amulet(i)") || lower.contains("salve amulet (i)"))
			{
				in.salveImbued = true;
			}
			else if (lower.contains("salve amulet"))
			{
				in.salve = true;
			}
		}
		else if (slot == EquipmentInventorySlot.WEAPON)
		{
			in.shadow = lower.contains("tumeken's shadow");
			in.twistedBow = lower.contains("twisted bow");
			in.fang = lower.contains("osmumten's fang");
			in.crystalBow = lower.contains("bow of faerdhinen") || lower.contains("crystal bow");
			in.arclight = lower.contains("arclight") && !lower.contains("inactive");
			in.emberlight = lower.contains("emberlight");
			in.darklight = lower.contains("darklight") || lower.contains("silverlight");
			in.dragonHunterLance = lower.contains("dragon hunter lance");
			in.dragonHunterCrossbow = lower.contains("dragon hunter crossbow");
			in.dragonHunterWand = lower.contains("dragon hunter wand");
			in.harmonisedStaff = lower.contains("harmonised");
			in.twinflameStaff = lower.contains("twinflame");
		}
		else if (slot == EquipmentInventorySlot.SHIELD)
		{
			if (lower.equals("tome of fire") || lower.startsWith("tome of fire ") && !lower.contains("uncharged") && !lower.contains("empty"))
			{
				in.tomeFire = !lower.contains("uncharged") && !lower.contains("empty");
			}
			if (lower.contains("tome of water") && !lower.contains("uncharged") && !lower.contains("empty"))
			{
				in.tomeWater = true;
			}
			if (lower.contains("tome of earth") && !lower.contains("uncharged") && !lower.contains("empty"))
			{
				in.tomeEarth = true;
			}
		}
		if (lower.contains("slayer helmet") || lower.contains("black mask (i)") || lower.contains("black mask(i)"))
		{
			in.blackMaskImbued = true;
		}
		else if (lower.contains("black mask"))
		{
			in.blackMask = true;
		}
	}

	private static void finishVoid(CombatInput in, String head, String body, String legs, String gloves)
	{
		String headName = head.toLowerCase();
		String bodyName = body.toLowerCase();
		String legsName = legs.toLowerCase();
		String glovesName = gloves.toLowerCase();
		boolean glovesOk = glovesName.contains("void knight gloves") || glovesName.contains("void gloves");
		boolean eliteTop = bodyName.contains("elite void top");
		boolean eliteLegs = legsName.contains("elite void robe");
		boolean topOk = bodyName.contains("void knight top") || eliteTop;
		boolean legsOk = legsName.contains("void knight robe") || eliteLegs;
		boolean elite = eliteTop && eliteLegs;
		if (!glovesOk || !topOk || !legsOk)
		{
			return;
		}
		if (headName.contains("void melee helm"))
		{
			in.voidMelee = true;
		}
		else if (headName.contains("void ranger helm"))
		{
			in.voidRanged = true;
			in.voidRangedElite = elite;
		}
		else if (headName.contains("void mage helm"))
		{
			in.voidMagic = true;
			in.voidMagicElite = elite;
		}
	}

	private static boolean isPoweredStaff(String name)
	{
		String lower = name.toLowerCase();
		if (lower.contains("(a)") || isUncharged(lower))
		{
			return false;
		}
		return lower.contains("trident of the seas")
			|| lower.contains("trident of the swamp")
			|| lower.contains("sanguinesti")
			|| lower.contains("tumeken's shadow")
			|| lower.contains("warped sceptre")
			|| lower.contains("accursed sceptre")
			|| lower.contains("thammaron's sceptre")
			|| lower.contains("eye of ayak")
			|| lower.contains("bone staff")
			|| lower.contains("dawnbringer")
			|| lower.contains("starter staff");
	}

	private static boolean isUncharged(String name)
	{
		String lower = name.toLowerCase();
		return lower.contains("uncharged") || lower.contains("(empty)") || lower.contains("inactive");
	}

	private static MeleeStyle meleeStyle(ItemEquipmentStats weapon, Client client)
	{
		if (weapon == null)
		{
			return MeleeStyle.SLASH;
		}
		int stab = weapon.getAstab();
		int slash = weapon.getAslash();
		int crush = weapon.getAcrush();
		if (stab == slash && slash == crush)
		{
			int index = client.getVarpValue(VarPlayerID.COM_MODE);
			if (index == 1)
			{
				return MeleeStyle.SLASH;
			}
			if (index == 2)
			{
				return MeleeStyle.CRUSH;
			}
			return MeleeStyle.STAB;
		}
		if (crush >= stab && crush >= slash)
		{
			return MeleeStyle.CRUSH;
		}
		if (slash >= stab)
		{
			return MeleeStyle.SLASH;
		}
		return MeleeStyle.STAB;
	}

	private static RangedStyle rangedStyle(String weaponName)
	{
		String lower = weaponName.toLowerCase();
		if (lower.contains("blowpipe") || lower.contains("dart") || lower.contains("knife")
			|| lower.contains("thrownaxe") || lower.contains("toktz-xil-ul") || lower.contains("tonalztics"))
		{
			return RangedStyle.LIGHT;
		}
		if (lower.contains("crossbow") || lower.contains("ballista") || lower.contains("chinchompa")
			|| lower.contains("javelin"))
		{
			return RangedStyle.HEAVY;
		}
		return RangedStyle.STANDARD;
	}

	private static void applyPrayers(Client client, CombatInput in)
	{
		PrayerBonus.apply(in, PrayerBonus.active(client));
	}

	private static StyleSelection readStyle(Client client)
	{
		try
		{
			int weaponType = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
			int index = client.getVarpValue(VarPlayerID.COM_MODE);
			int castingMode = client.getVarbitValue(VarbitID.AUTOCAST_DEFMODE);
			if (index == 4)
			{
				index += castingMode;
			}
			String[] names;
			if (weaponType == 22)
			{
				names = new String[]{"Accurate", "Aggressive", null, "Defensive", "Casting", "Defensive Casting"};
			}
			else if (weaponType == 30)
			{
				names = new String[]{"Accurate", "Aggressive", "Aggressive", "Defensive"};
			}
			else
			{
				int weaponStyleEnum = client.getEnum(EnumID.WEAPON_STYLES).getIntValue(weaponType);
				if (weaponStyleEnum == -1)
				{
					return StyleSelection.empty();
				}
				EnumComposition styles = client.getEnum(weaponStyleEnum);
				int[] structs = styles.getIntVals();
				names = new String[structs.length];
				int cursor = 0;
				for (int style : structs)
				{
					StructComposition composition = client.getStructComposition(style);
					String name = composition.getStringValue(ParamID.ATTACK_STYLE_NAME);
					if (name != null && "Other".equalsIgnoreCase(name))
					{
						cursor++;
						continue;
					}
					if (cursor == 5 && name != null && "Defensive".equalsIgnoreCase(name))
					{
						name = "Defensive Casting";
					}
					if (cursor < names.length)
					{
						names[cursor] = name;
					}
					cursor++;
				}
			}
			return StyleSelection.of(names, index);
		}
		catch (RuntimeException ex)
		{
			return StyleSelection.empty();
		}
	}

	/**
	 * The cache names both the accurate and rapid ranged buttons "Ranging".
	 * On a bow the first is accurate and the second is rapid. A lone "Ranging"
	 * that is not the first button, such as a salamander's flare, is rapid.
	 */
	static AttackStance stanceFrom(StyleSelection style, boolean poweredStaff)
	{
		if (style == null || style.name == null || style.name.isEmpty())
		{
			return poweredStaff ? AttackStance.MAGIC_ACCURATE : AttackStance.MELEE_AGGRESSIVE;
		}
		String lower = style.name.toLowerCase();
		if (lower.contains("rapid"))
		{
			return promotePoweredStaff(AttackStance.RANGED_RAPID, poweredStaff);
		}
		if (lower.contains("longrange"))
		{
			return promotePoweredStaff(AttackStance.RANGED_LONG, poweredStaff);
		}
		if (lower.contains("ranging"))
		{
			boolean rapid = style.rangingTotal >= 2
				? style.rangingBefore > 0
				: style.index > 0;
			return promotePoweredStaff(rapid ? AttackStance.RANGED_RAPID : AttackStance.RANGED_ACCURATE, poweredStaff);
		}
		if (lower.contains("defensive casting"))
		{
			return promotePoweredStaff(AttackStance.MAGIC_DEFENSIVE, poweredStaff);
		}
		if (lower.contains("casting"))
		{
			return promotePoweredStaff(AttackStance.MAGIC_AUTOCAST, poweredStaff);
		}
		if (lower.contains("controlled"))
		{
			return promotePoweredStaff(AttackStance.MELEE_CONTROLLED, poweredStaff);
		}
		if (lower.contains("aggressive"))
		{
			return promotePoweredStaff(AttackStance.MELEE_AGGRESSIVE, poweredStaff);
		}
		if (lower.contains("defensive"))
		{
			return promotePoweredStaff(AttackStance.MELEE_DEFENSIVE, poweredStaff);
		}
		if (lower.contains("accurate"))
		{
			return promotePoweredStaff(AttackStance.MELEE_ACCURATE, poweredStaff);
		}
		return promotePoweredStaff(AttackStance.MELEE_AGGRESSIVE, poweredStaff);
	}

	private static AttackStance promotePoweredStaff(AttackStance stance, boolean poweredStaff)
	{
		if (!poweredStaff)
		{
			return stance;
		}
		if (stance == AttackStance.RANGED_LONG
			|| stance == AttackStance.MELEE_DEFENSIVE
			|| stance == AttackStance.MAGIC_DEFENSIVE)
		{
			return AttackStance.MAGIC_DEFENSIVE;
		}
		return AttackStance.MAGIC_ACCURATE;
	}

	static final class StyleSelection
	{
		final String name;
		final int index;
		final int rangingBefore;
		final int rangingTotal;

		private StyleSelection(String name, int index, int rangingBefore, int rangingTotal)
		{
			this.name = name;
			this.index = index;
			this.rangingBefore = rangingBefore;
			this.rangingTotal = rangingTotal;
		}

		static StyleSelection empty()
		{
			return new StyleSelection("", 0, 0, 0);
		}

		static StyleSelection of(String[] names, int index)
		{
			int rangingBefore = 0;
			int rangingTotal = 0;
			String selected = "";
			if (names != null)
			{
				for (int i = 0; i < names.length; i++)
				{
					String name = names[i];
					if (name != null && name.toLowerCase().contains("ranging"))
					{
						if (i < index)
						{
							rangingBefore++;
						}
						rangingTotal++;
					}
					if (i == index && name != null)
					{
						selected = name;
					}
				}
			}
			return new StyleSelection(selected, index, rangingBefore, rangingTotal);
		}
	}

	private static String itemName(ItemManager itemManager, int itemId)
	{
		String name = itemManager.getItemComposition(itemId).getName();
		if (name == null)
		{
			return "";
		}
		return name.replace('\u00A0', ' ').trim();
	}
}

package com.marmaduke.dps;

import java.util.Locale;

/**
 * Combat-potion boosts using the same integer percent rules as RuneLite's item stats:
 * a boost is added to the current level and capped at base + boost. A drain is taken off
 * the current level. Drinking is hypothetical; the caller keeps the live levels unchanged.
 */
final class PotionBoosts
{
	private PotionBoosts()
	{
	}

	static void apply(CombatInput in, int baseAttack, int baseStrength, int baseRanged, int baseMagic, String itemName)
	{
		String name = canonical(itemName);
		if (!affectsCombat(itemName) || name == null)
		{
			return;
		}
		if (name.startsWith("overload (+)"))
		{
			boostAll(in, baseAttack, baseStrength, baseRanged, baseMagic, 0.16, 6);
		}
		else if (name.startsWith("overload (-)"))
		{
			boostAll(in, baseAttack, baseStrength, baseRanged, baseMagic, 0.10, 4);
		}
		else if (name.startsWith("overload"))
		{
			boost(in, SkillStat.ATTACK, baseAttack, 0.15, 5);
			boost(in, SkillStat.STRENGTH, baseStrength, 0.15, 5);
			boost(in, SkillStat.RANGED, baseRanged, 0.15, 5);
			boost(in, SkillStat.MAGIC, baseMagic, 0.15, 5);
		}
		else if (name.startsWith("smelling salt"))
		{
			boostAll(in, baseAttack, baseStrength, baseRanged, baseMagic, 0.16, 11);
		}
		else if (name.startsWith("elder (+)"))
		{
			boost(in, SkillStat.ATTACK, baseAttack, 0.16, 6);
			boost(in, SkillStat.STRENGTH, baseStrength, 0.16, 6);
		}
		else if (name.startsWith("elder (-)"))
		{
			boost(in, SkillStat.ATTACK, baseAttack, 0.10, 4);
			boost(in, SkillStat.STRENGTH, baseStrength, 0.10, 4);
		}
		else if (name.startsWith("elder"))
		{
			boost(in, SkillStat.ATTACK, baseAttack, 0.13, 5);
			boost(in, SkillStat.STRENGTH, baseStrength, 0.13, 5);
		}
		else if (name.startsWith("twisted (+)"))
		{
			boost(in, SkillStat.RANGED, baseRanged, 0.16, 6);
		}
		else if (name.startsWith("twisted (-)"))
		{
			boost(in, SkillStat.RANGED, baseRanged, 0.10, 4);
		}
		else if (name.startsWith("twisted potion"))
		{
			boost(in, SkillStat.RANGED, baseRanged, 0.13, 5);
		}
		else if (name.startsWith("kodai (+)"))
		{
			boost(in, SkillStat.MAGIC, baseMagic, 0.16, 6);
		}
		else if (name.startsWith("kodai (-)"))
		{
			boost(in, SkillStat.MAGIC, baseMagic, 0.10, 4);
		}
		else if (name.startsWith("kodai"))
		{
			boost(in, SkillStat.MAGIC, baseMagic, 0.13, 5);
		}
		else if (name.startsWith("super combat"))
		{
			boost(in, SkillStat.ATTACK, baseAttack, 0.15, 5);
			boost(in, SkillStat.STRENGTH, baseStrength, 0.15, 5);
		}
		else if (name.startsWith("bastion"))
		{
			boost(in, SkillStat.RANGED, baseRanged, 0.10, 4);
		}
		else if (name.startsWith("battlemage"))
		{
			boost(in, SkillStat.MAGIC, baseMagic, 0, 4);
		}
		else if (name.startsWith("zamorak brew"))
		{
			boost(in, SkillStat.ATTACK, baseAttack, 0.20, 2);
			boost(in, SkillStat.STRENGTH, baseStrength, 0.12, 2);
		}
		else if (name.startsWith("saradomin brew"))
		{
			drain(in, SkillStat.ATTACK, 0.10, 2);
			drain(in, SkillStat.STRENGTH, 0.10, 2);
			drain(in, SkillStat.RANGED, 0.10, 2);
			drain(in, SkillStat.MAGIC, 0.10, 2);
		}
		else if (name.startsWith("forgotten brew"))
		{
			boost(in, SkillStat.MAGIC, baseMagic, 0.08, 3);
			drain(in, SkillStat.ATTACK, 0.10, 2);
			drain(in, SkillStat.STRENGTH, 0.10, 2);
		}
		else if (name.startsWith("ancient brew"))
		{
			boost(in, SkillStat.MAGIC, baseMagic, 0.05, 2);
			drain(in, SkillStat.ATTACK, 0.10, 2);
			drain(in, SkillStat.STRENGTH, 0.10, 2);
		}
		else if (name.startsWith("armadyl brew"))
		{
			boost(in, SkillStat.RANGED, baseRanged, 0.10, 4);
			drain(in, SkillStat.ATTACK, 0.10, 2);
			drain(in, SkillStat.STRENGTH, 0.10, 2);
			drain(in, SkillStat.MAGIC, 0.10, 2);
		}
		else if (name.startsWith("super ranging") || name.startsWith("ranging"))
		{
			if (name.startsWith("super ranging"))
			{
				boost(in, SkillStat.RANGED, baseRanged, 0.15, 5);
			}
			else
			{
				boost(in, SkillStat.RANGED, baseRanged, 0.10, 4);
			}
		}
		else if (name.startsWith("super magic"))
		{
			boost(in, SkillStat.MAGIC, baseMagic, 0.15, 5);
		}
		else if (name.startsWith("magic essence"))
		{
			boost(in, SkillStat.MAGIC, baseMagic, 0, 3);
		}
		else if (name.startsWith("magic potion") || name.startsWith("magic mix"))
		{
			boost(in, SkillStat.MAGIC, baseMagic, 0, 4);
		}
		else if (name.startsWith("super attack"))
		{
			boost(in, SkillStat.ATTACK, baseAttack, 0.15, 5);
		}
		else if (name.startsWith("super strength"))
		{
			boost(in, SkillStat.STRENGTH, baseStrength, 0.15, 5);
		}
		else if (name.startsWith("combat"))
		{
			boost(in, SkillStat.ATTACK, baseAttack, 0.10, 3);
			boost(in, SkillStat.STRENGTH, baseStrength, 0.10, 3);
		}
		else if (name.startsWith("attack"))
		{
			boost(in, SkillStat.ATTACK, baseAttack, 0.10, 3);
		}
		else if (name.startsWith("strength"))
		{
			boost(in, SkillStat.STRENGTH, baseStrength, 0.10, 3);
		}
	}

	static boolean affectsCombat(String itemName)
	{
		String name = canonical(itemName);
		if (name == null || !isDrink(name))
		{
			return false;
		}
		return name.startsWith("overload")
			|| name.startsWith("smelling salt")
			|| name.startsWith("elder")
			|| name.startsWith("twisted (+)")
			|| name.startsWith("twisted (-)")
			|| name.startsWith("twisted potion")
			|| name.startsWith("kodai")
			|| name.startsWith("super combat")
			|| name.startsWith("bastion")
			|| name.startsWith("battlemage")
			|| name.startsWith("zamorak brew")
			|| name.startsWith("saradomin brew")
			|| name.startsWith("forgotten brew")
			|| name.startsWith("ancient brew")
			|| name.startsWith("armadyl brew")
			|| name.startsWith("super ranging")
			|| name.startsWith("ranging")
			|| name.startsWith("super magic")
			|| name.startsWith("magic essence")
			|| name.startsWith("magic potion")
			|| name.startsWith("magic mix")
			|| name.startsWith("super attack")
			|| name.startsWith("super strength")
			|| name.startsWith("combat")
			|| name.startsWith("attack")
			|| name.startsWith("strength");
	}

	private static boolean isDrink(String name)
	{
		return name.contains("potion")
			|| name.contains("brew")
			|| name.contains("overload")
			|| name.contains("smelling salt")
			|| name.contains("essence")
			|| name.endsWith("(+) ")
			|| name.endsWith("(+)")
			|| name.endsWith("(-)")
			|| "super attack".equals(name)
			|| "super strength".equals(name);
	}

	private static String canonical(String itemName)
	{
		if (itemName == null)
		{
			return null;
		}
		String name = itemName.toLowerCase(Locale.US);
		name = name.replace("blighted ", "");
		name = name.replace("divine ", "");
		name = name.replaceAll("\\(\\d+\\)", "");
		name = name.replace(" mix", "");
		name = name.trim();
		if (name.isEmpty())
		{
			return null;
		}
		return name;
	}

	private static void boostAll(CombatInput in, int baseAttack, int baseStrength, int baseRanged, int baseMagic, double percent, int flat)
	{
		boost(in, SkillStat.ATTACK, baseAttack, percent, flat);
		boost(in, SkillStat.STRENGTH, baseStrength, percent, flat);
		boost(in, SkillStat.RANGED, baseRanged, percent, flat);
		boost(in, SkillStat.MAGIC, baseMagic, percent, flat);
	}

	private static void boost(CombatInput in, SkillStat stat, int base, double percent, int flat)
	{
		int current = stat.get(in);
		int delta = (int) (base * percent) + flat;
		if (delta <= 0)
		{
			stat.set(in, Math.max(current, base + delta));
			return;
		}
		int cap = base + delta;
		if (current > cap)
		{
			return;
		}
		int raised = current + delta;
		if (raised > cap)
		{
			raised = cap;
		}
		stat.set(in, raised);
	}

	private static void drain(CombatInput in, SkillStat stat, double percent, int flat)
	{
		int current = stat.get(in);
		int next = current - (int) (current * percent) - flat;
		if (next < 0)
		{
			next = 0;
		}
		stat.set(in, next);
	}

	private enum SkillStat
	{
		ATTACK,
		STRENGTH,
		RANGED,
		MAGIC;

		int get(CombatInput in)
		{
			switch (this)
			{
				case ATTACK:
					return in.attackLevel;
				case STRENGTH:
					return in.strengthLevel;
				case RANGED:
					return in.rangedLevel;
				case MAGIC:
				default:
					return in.magicLevel;
			}
		}

		void set(CombatInput in, int value)
		{
			switch (this)
			{
				case ATTACK:
					in.attackLevel = value;
					break;
				case STRENGTH:
					in.strengthLevel = value;
					break;
				case RANGED:
					in.rangedLevel = value;
					break;
				case MAGIC:
				default:
					in.magicLevel = value;
					break;
			}
		}
	}
}

package com.marmaduke.dps;

import java.util.EnumSet;
import net.runelite.api.Client;
import net.runelite.api.Prayer;

/**
 * Offensive prayer multipliers. Only one prayer in each style group applies, matching the
 * client: turning Rigour on turns Eagle Eye off, and the same for the melee and magic groups.
 */
final class PrayerBonus
{
	private PrayerBonus()
	{
	}

	static EnumSet<Prayer> active(Client client)
	{
		EnumSet<Prayer> prayers = EnumSet.noneOf(Prayer.class);
		Prayer[] all = Prayer.values();
		for (int i = 0; i < all.length; i++)
		{
			if (client.isPrayerActive(all[i]))
			{
				prayers.add(all[i]);
			}
		}
		return prayers;
	}

	static EnumSet<Prayer> toggle(EnumSet<Prayer> active, Prayer prayer)
	{
		EnumSet<Prayer> next = EnumSet.noneOf(Prayer.class);
		if (active != null)
		{
			next.addAll(active);
		}
		if (next.contains(prayer))
		{
			next.remove(prayer);
			return next;
		}
		next.add(prayer);
		clearGroup(next, prayer);
		return next;
	}

	static void apply(CombatInput in, EnumSet<Prayer> active)
	{
		in.meleeAttackPrayer = 100;
		in.meleeStrengthPrayer = 100;
		in.rangedAttackPrayer = 100;
		in.rangedStrengthPrayer = 100;
		in.magicAttackPrayer = 100;
		in.magicDamagePrayerPermille = 0;
		if (active == null || active.isEmpty())
		{
			return;
		}

		if (active.contains(Prayer.ZEAL))
		{
			in.meleeAttackPrayer = 125;
			in.meleeStrengthPrayer = 128;
		}
		else if (active.contains(Prayer.PIETY))
		{
			in.meleeAttackPrayer = 120;
			in.meleeStrengthPrayer = 123;
		}
		else if (active.contains(Prayer.CHIVALRY))
		{
			in.meleeAttackPrayer = 115;
			in.meleeStrengthPrayer = 118;
		}
		else
		{
			if (active.contains(Prayer.ULTIMATE_STRENGTH))
			{
				in.meleeStrengthPrayer = 115;
			}
			else if (active.contains(Prayer.SUPERHUMAN_STRENGTH))
			{
				in.meleeStrengthPrayer = 110;
			}
			else if (active.contains(Prayer.BURST_OF_STRENGTH))
			{
				in.meleeStrengthPrayer = 105;
			}
			if (active.contains(Prayer.INCREDIBLE_REFLEXES))
			{
				in.meleeAttackPrayer = 115;
			}
			else if (active.contains(Prayer.IMPROVED_REFLEXES))
			{
				in.meleeAttackPrayer = 110;
			}
			else if (active.contains(Prayer.CLARITY_OF_THOUGHT))
			{
				in.meleeAttackPrayer = 105;
			}
		}

		if (active.contains(Prayer.RIGOUR))
		{
			in.rangedAttackPrayer = 120;
			in.rangedStrengthPrayer = 123;
		}
		else if (active.contains(Prayer.DEADEYE))
		{
			in.rangedAttackPrayer = 118;
			in.rangedStrengthPrayer = 118;
		}
		else if (active.contains(Prayer.EAGLE_EYE))
		{
			in.rangedAttackPrayer = 115;
			in.rangedStrengthPrayer = 115;
		}
		else if (active.contains(Prayer.HAWK_EYE))
		{
			in.rangedAttackPrayer = 110;
			in.rangedStrengthPrayer = 110;
		}
		else if (active.contains(Prayer.SHARP_EYE))
		{
			in.rangedAttackPrayer = 105;
			in.rangedStrengthPrayer = 105;
		}

		if (active.contains(Prayer.AUGURY))
		{
			in.magicAttackPrayer = 125;
			in.magicDamagePrayerPermille = 40;
		}
		else if (active.contains(Prayer.MYSTIC_VIGOUR))
		{
			in.magicAttackPrayer = 118;
			in.magicDamagePrayerPermille = 30;
		}
		else if (active.contains(Prayer.MYSTIC_MIGHT))
		{
			in.magicAttackPrayer = 115;
			in.magicDamagePrayerPermille = 20;
		}
		else if (active.contains(Prayer.MYSTIC_LORE))
		{
			in.magicAttackPrayer = 110;
			in.magicDamagePrayerPermille = 10;
		}
		else if (active.contains(Prayer.MYSTIC_WILL))
		{
			in.magicAttackPrayer = 105;
		}
	}

	private static void clearGroup(EnumSet<Prayer> next, Prayer prayer)
	{
		if (prayer == Prayer.ZEAL || prayer == Prayer.PIETY || prayer == Prayer.CHIVALRY)
		{
			remove(next, prayer, Prayer.ZEAL, Prayer.PIETY, Prayer.CHIVALRY,
				Prayer.ULTIMATE_STRENGTH, Prayer.SUPERHUMAN_STRENGTH, Prayer.BURST_OF_STRENGTH,
				Prayer.INCREDIBLE_REFLEXES, Prayer.IMPROVED_REFLEXES, Prayer.CLARITY_OF_THOUGHT);
		}
		else if (prayer == Prayer.ULTIMATE_STRENGTH
			|| prayer == Prayer.SUPERHUMAN_STRENGTH
			|| prayer == Prayer.BURST_OF_STRENGTH)
		{
			remove(next, prayer, Prayer.ZEAL, Prayer.PIETY, Prayer.CHIVALRY,
				Prayer.ULTIMATE_STRENGTH, Prayer.SUPERHUMAN_STRENGTH, Prayer.BURST_OF_STRENGTH);
		}
		else if (prayer == Prayer.INCREDIBLE_REFLEXES
			|| prayer == Prayer.IMPROVED_REFLEXES
			|| prayer == Prayer.CLARITY_OF_THOUGHT)
		{
			remove(next, prayer, Prayer.ZEAL, Prayer.PIETY, Prayer.CHIVALRY,
				Prayer.INCREDIBLE_REFLEXES, Prayer.IMPROVED_REFLEXES, Prayer.CLARITY_OF_THOUGHT);
		}
		else if (prayer == Prayer.RIGOUR
			|| prayer == Prayer.DEADEYE
			|| prayer == Prayer.EAGLE_EYE
			|| prayer == Prayer.HAWK_EYE
			|| prayer == Prayer.SHARP_EYE)
		{
			remove(next, prayer, Prayer.RIGOUR, Prayer.DEADEYE, Prayer.EAGLE_EYE, Prayer.HAWK_EYE, Prayer.SHARP_EYE);
		}
		else if (prayer == Prayer.AUGURY
			|| prayer == Prayer.MYSTIC_VIGOUR
			|| prayer == Prayer.MYSTIC_MIGHT
			|| prayer == Prayer.MYSTIC_LORE
			|| prayer == Prayer.MYSTIC_WILL)
		{
			remove(next, prayer, Prayer.AUGURY, Prayer.MYSTIC_VIGOUR, Prayer.MYSTIC_MIGHT,
				Prayer.MYSTIC_LORE, Prayer.MYSTIC_WILL);
		}
	}

	private static void remove(EnumSet<Prayer> next, Prayer keep, Prayer... group)
	{
		for (int i = 0; i < group.length; i++)
		{
			if (group[i] != keep)
			{
				next.remove(group[i]);
			}
		}
	}
}

