		standard(spells, 11, "Earth Blast", 15, "earth");
		standard(spells, 12, "Fire Blast", 16, "fire");
		standard(spells, 13, "Wind Wave", 17, "air");
		standard(spells, 14, "Water Wave", 18, "water");
		standard(spells, 15, "Earth Wave", 19, "earth");
		standard(spells, 16, "Fire Wave", 20, "fire");
		standard(spells, 17, "Crumble Undead", 15, "");
		standard(spells, 18, "Magic Dart", 0, "");
		standard(spells, 19, "Claws of Guthix", 20, "");
		standard(spells, 20, "Flames of Zamorak", 20, "");
		ancient(spells, 31, "Smoke Rush", 13);
		ancient(spells, 32, "Shadow Rush", 14);
		ancient(spells, 33, "Blood Rush", 15);
		ancient(spells, 34, "Ice Rush", 16);
		ancient(spells, 35, "Smoke Burst", 17);
		ancient(spells, 36, "Shadow Burst", 18);
		ancient(spells, 37, "Blood Burst", 21);
		ancient(spells, 38, "Ice Burst", 22);
		ancient(spells, 39, "Smoke Blitz", 23);
		ancient(spells, 40, "Shadow Blitz", 24);
		ancient(spells, 41, "Blood Blitz", 25);
		ancient(spells, 42, "Ice Blitz", 26);
		ancient(spells, 43, "Smoke Barrage", 27);
		ancient(spells, 44, "Shadow Barrage", 28);
		ancient(spells, 45, "Blood Barrage", 29);
		ancient(spells, 46, "Ice Barrage", 30);
		standard(spells, 47, "Iban Blast", 25, "");
		standard(spells, 48, "Wind Surge", 21, "air");
		standard(spells, 49, "Water Surge", 22, "water");
		standard(spells, 50, "Earth Surge", 23, "earth");
		standard(spells, 51, "Fire Surge", 24, "fire");
		standard(spells, 52, "Saradomin Strike", 20, "");
		arceuus(spells, 53, "Inferior Demonbane", 16);
		arceuus(spells, 54, "Superior Demonbane", 23);
		arceuus(spells, 55, "Dark Demonbane", 30);
		arceuus(spells, 56, "Ghostly Grasp", 12);
		arceuus(spells, 57, "Skeletal Grasp", 17);
		arceuus(spells, 58, "Undead Grasp", 24);
		return Collections.unmodifiableMap(spells);
	}

	private static void standard(Map<Integer, SpellTable> spells, int id, String name, int maxHit, String element)
	{
		spells.put(id, new SpellTable(name, maxHit, element, "standard"));
	}

	private static void ancient(Map<Integer, SpellTable> spells, int id, String name, int maxHit)
	{
		spells.put(id, new SpellTable(name, maxHit, "", "ancient"));
	}

	private static void arceuus(Map<Integer, SpellTable> spells, int id, String name, int maxHit)
	{
		spells.put(id, new SpellTable(name, maxHit, "", "arceuus"));
	}
}

package com.marmaduke.dps;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class CombatMathTest
{
	@Test
	public void rapidTwistedBowDoesNotMatchAccurate()
	{
		CombatInput rapid = twistedBow(AttackStance.RANGED_RAPID);
		CombatInput accurate = twistedBow(AttackStance.RANGED_ACCURATE);

		assertTrue(CombatMath.maxHit(rapid) < CombatMath.maxHit(accurate));
		assertTrue(CombatMath.attackRoll(rapid) < CombatMath.attackRoll(accurate));
		assertEquals(5, CombatMath.attackSpeed(rapid));
		assertEquals(6, CombatMath.attackSpeed(accurate));
		assertEquals("Rapid", CombatMath.estimate(rapid, "Target", "Def 0").styleLabel);
		assertEquals("Accurate", CombatMath.estimate(accurate, "Target", "Def 0").styleLabel);
		rapid.rangedStyle = RangedStyle.LIGHT;
		assertEquals("Rapid (light)", CombatMath.estimate(rapid, "Target", "Def 0").styleLabel);
	}

	@Test
	public void secondRangingStyleIsRapid()
	{
		String[] bow = new String[]{"Ranging", "Ranging", null, "Longrange"};
		assertEquals(AttackStance.RANGED_ACCURATE, PlayerGear.stanceFrom(PlayerGear.StyleSelection.of(bow, 0), false));
		assertEquals(AttackStance.RANGED_RAPID, PlayerGear.stanceFrom(PlayerGear.StyleSelection.of(bow, 1), false));
		assertEquals(AttackStance.RANGED_LONG, PlayerGear.stanceFrom(PlayerGear.StyleSelection.of(bow, 3), false));

		String[] salamander = new String[]{"Aggressive", "Ranging", "Casting"};
		assertEquals(AttackStance.RANGED_RAPID, PlayerGear.stanceFrom(PlayerGear.StyleSelection.of(salamander, 1), false));
		assertEquals(AttackStance.MAGIC_AUTOCAST, PlayerGear.stanceFrom(PlayerGear.StyleSelection.of(salamander, 2), false));
		assertEquals(AttackStance.MAGIC_ACCURATE, PlayerGear.stanceFrom(PlayerGear.StyleSelection.of(salamander, 2), true));
	}

	@Test
	public void staffAutocastDoesNotUseTheAccurateMagicBonus()
	{
		CombatInput autocast = new CombatInput();
		autocast.combatStyle = CombatStyle.MAGIC;
		autocast.stance = AttackStance.MAGIC_AUTOCAST;
		autocast.magicLevel = 99;
		autocast.magicBonus = 10;
		autocast.spellName = "Fire Surge";
		autocast.spellMaxHit = 24;

		CombatInput accurate = new CombatInput();
		accurate.combatStyle = CombatStyle.MAGIC;
		accurate.stance = AttackStance.MAGIC_ACCURATE;
		accurate.magicLevel = 99;
		accurate.magicBonus = 10;
		accurate.spellName = "Fire Surge";
		accurate.spellMaxHit = 24;

		assertTrue(CombatMath.attackRoll(accurate) > CombatMath.attackRoll(autocast));
		assertEquals(CombatMath.maxHit(accurate), CombatMath.maxHit(autocast));
	}

	@Test
	public void aggressiveMaxHitBeatsDefensive()
	{
		CombatInput aggressive = new CombatInput();
		aggressive.strengthLevel = 99;
		aggressive.stance = AttackStance.MELEE_AGGRESSIVE;
		aggressive.strengthBonus = 86;

		CombatInput defensive = new CombatInput();
		defensive.strengthLevel = 99;
		defensive.stance = AttackStance.MELEE_DEFENSIVE;
		defensive.strengthBonus = 86;

		assertTrue(CombatMath.maxHit(aggressive) > CombatMath.maxHit(defensive));
	}

	@Test
	public void meleeMaxHitUsesPietyAndAggressiveStyle()
	{
		CombatInput in = new CombatInput();
		in.strengthLevel = 99;
		in.meleeStrengthPrayer = 123;
		in.stance = AttackStance.MELEE_AGGRESSIVE;
		in.strengthBonus = 86;

		assertEquals(31, CombatMath.maxHit(in));
	}

	@Test
	public void abyssalDemonSlashDefenceRoll()
	{
		CombatInput in = new CombatInput();
		in.combatStyle = CombatStyle.MELEE;
		in.meleeStyle = MeleeStyle.SLASH;
		in.npcDefence = 135;
		in.npcSlash = 20;

		assertEquals(12096, CombatMath.defenceRoll(in));
	}

	@Test
	public void tridentMaxHitAt99()
	{
		CombatInput in = new CombatInput();
		in.combatStyle = CombatStyle.MAGIC;
		in.poweredStaff = true;
		in.magicLevel = 99;
		in.weaponName = "Trident of the seas";

		assertEquals(28, CombatMath.maxHit(in));
	}

	@Test
	public void shadowTriplesMagicDamageOutsideTombs()
	{
		CombatInput in = new CombatInput();
		in.combatStyle = CombatStyle.MAGIC;
		in.poweredStaff = true;
		in.shadow = true;
		in.magicLevel = 99;
		in.weaponName = "Tumeken's shadow";
		in.magicDamagePermille = 100;

		assertEquals(44, CombatMath.maxHit(in));
	}

	@Test
	public void fireSurgeAddsOccultThenSlayerHelm()
	{
		CombatInput in = new CombatInput();
		in.combatStyle = CombatStyle.MAGIC;
		in.spellName = "Fire Surge";
		in.spellMaxHit = 24;
		in.spellElement = "fire";
		in.spellbook = "standard";
		in.magicDamagePermille = 100;
		in.blackMaskImbued = true;
		in.onSlayerTask = true;

		assertEquals(29, CombatMath.maxHit(in));
	}

	@Test
	public void expectedDamageIsHalfTheMaxHitWhenEveryRollHits()
	{
		assertEquals(5.0, CombatMath.expectedDamage(1.0, 10, 0), 0.0001);
	}

	@Test
	public void flatArmourRemovesDamageFromSuccessfulRolls()
	{
		assertEquals(0.6, CombatMath.expectedDamage(1.0, 4, 2), 0.0001);
	}

	@Test
	public void twistedBowAccuracyFloorAtZeroMagic()
	{
		assertEquals(40, CombatMath.tbowScale(100, 0, true));
	}

	@Test
	public void dpsDividesExpectedDamageByAttackInterval()
	{
		CombatInput in = new CombatInput();
		in.strengthLevel = 99;
		in.attackLevel = 99;
		in.meleeAttackPrayer = 100;
		in.meleeStrengthPrayer = 100;
		in.stance = AttackStance.MELEE_AGGRESSIVE;
		in.strengthBonus = 0;
		in.slashBonus = 0;
		in.meleeStyle = MeleeStyle.SLASH;
		in.npcDefence = 0;
		in.npcSlash = -64;
		in.weaponSpeed = 4;

		DpsEstimate estimate = CombatMath.estimate(in, "Dummy", "Def 0");
		assertEquals(4, estimate.attackSpeedTicks);
		double expected = CombatMath.expectedDamage(estimate.accuracy, estimate.maxHit, 0);
		assertEquals(expected / 2.4, estimate.dps, 0.0001);
	}

	private static CombatInput twistedBow(AttackStance stance)
	{
		CombatInput in = new CombatInput();
		in.combatStyle = CombatStyle.RANGED;
		in.stance = stance;
		in.rangedStyle = RangedStyle.STANDARD;
		in.rangedLevel = 99;
		in.rangedBonus = 70;
		in.rangedStrengthBonus = 80;
		in.weaponSpeed = 6;
		in.twistedBow = true;
		in.weaponName = "Twisted bow";
		in.npcMagic = 100;
		in.npcOffensiveMagic = 0;
		return in;
	}
}

package com.marmaduke.dps;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class DefenceModelTest
{
	@Test
	public void overlayShowsOriginalMinusTheReduction()
	{
		DefenceModel reduced = new DefenceModel(stats(90));
		reduced.applyBandosGodsword(30);
		assertEquals(60, reduced.defence);
		assertEquals("90-30", reduced.overlayDefence());

		DefenceModel untouched = new DefenceModel(stats(90));
		assertEquals("90", untouched.overlayDefence());
	}

	@Test
	public void dragonWarhammerStacksOnTheCurrentLevel()
	{
		DefenceModel model = new DefenceModel(stats(135));
		model.applyDragonWarhammer(false);
		assertEquals(95, model.defence);
		model.applyDragonWarhammer(false);
		assertEquals(67, model.defence);
		assertTrue(model.describe().contains("DWH x2"));
	}

	@Test
	public void bandosGodswordDrainsDefenceBeforeStrength()
	{
		NpcCombatStats stats = stats(30);
		stats.str = 40;
		stats.atk = 10;
		stats.magic = 5;
		DefenceModel model = new DefenceModel(stats);
		model.applyBandosGodsword(50);

		assertEquals(0, model.defence);
		assertEquals(20, model.strength);
		assertEquals(10, model.attack);
		assertEquals(5, model.magic);
	}

	@Test
	public void accursedSceptreStopsAtFifteenPercent()
	{
		DefenceModel model = new DefenceModel(stats(100));
		model.applyAccursedSceptre();
		assertEquals(85, model.defence);
		assertEquals(85, model.magic);
		model.applyAccursedSceptre();
		assertEquals(85, model.defence);
	}

	@Test
	public void vulnerabilityExpiresAfterOneMinute()
	{
		DefenceModel model = new DefenceModel(stats(100));
		model.applyVulnerability(10);
		assertEquals(90, model.defence);
		for (int tick = 0; tick < 99; tick++)
		{
			model.tick();
		}
		assertEquals(90, model.defence);
		model.tick();
		assertEquals(100, model.defence);
	}

	private static NpcCombatStats stats(int defence)
	{
		NpcCombatStats stats = new NpcCombatStats();
		stats.def = defence;
		stats.magic = defence;
		stats.atk = 1;
		stats.str = 1;
		stats.ranged = 1;
		return stats;
	}
}

package com.marmaduke.dps;

import java.util.EnumSet;
import net.runelite.api.Prayer;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DpsDeltaTest
{
	@Test
	public void rigourOnRangedIsAGainAndDoesNotChangeTheLiveInput()
	{
		CombatInput current = ranged();
		int level = current.rangedLevel;
		int prayer = current.rangedAttackPrayer;

		Double delta = DpsDelta.prayer(current, EnumSet.noneOf(Prayer.class), Prayer.RIGOUR);

		assertTrue(delta.doubleValue() > 0);
		assertEquals(level, current.rangedLevel);
		assertEquals(prayer, current.rangedAttackPrayer);
		assertTrue(DpsDelta.format(delta.doubleValue()).startsWith("+"));
		assertTrue(DpsDelta.format(delta.doubleValue()).endsWith(" DPS"));
	}

	@Test
	public void turningRigourOffIsALoss()
	{
		CombatInput current = ranged();
		EnumSet<Prayer> active = EnumSet.of(Prayer.RIGOUR);
		PrayerBonus.apply(current, active);

		Double delta = DpsDelta.prayer(current, active, Prayer.RIGOUR);

		assertTrue(delta.doubleValue() < 0);
	}

	@Test
	public void rigourReplacesEagleEyeInsteadOfStacking()
	{
		EnumSet<Prayer> active = EnumSet.of(Prayer.EAGLE_EYE);
		EnumSet<Prayer> toggled = PrayerBonus.toggle(active, Prayer.RIGOUR);

		assertTrue(toggled.contains(Prayer.RIGOUR));
		assertFalse(toggled.contains(Prayer.EAGLE_EYE));

		CombatInput withEagle = ranged();
		PrayerBonus.apply(withEagle, active);
		CombatInput withRigour = ranged();
		PrayerBonus.apply(withRigour, toggled);
		assertTrue(withRigour.rangedStrengthPrayer > withEagle.rangedStrengthPrayer);
	}

	@Test
	public void rangingPotionRaisesDpsUntilTheBoostIsAlreadyActive()
	{
		CombatInput current = ranged();
		Double delta = DpsDelta.potion(current, 99, 99, 99, 99, "Ranging potion(4)");

		assertTrue(delta.doubleValue() > 0);
		assertEquals(99, current.rangedLevel);

		current.rangedLevel = 112;
		Double already = DpsDelta.potion(current, 99, 99, 99, 99, "Divine ranging potion(2)");
		assertEquals(0.0, already.doubleValue(), 0.0001);
	}

	@Test
	public void saradominBrewLowersRangedDps()
	{
		Double delta = DpsDelta.potion(ranged(), 99, 99, 99, 99, "Saradomin brew(4)");
		assertTrue(delta.doubleValue() < 0);
	}

	@Test
	public void prayerHoverLabelMapsToThePrayer()
	{
		assertEquals(Prayer.RIGOUR, DpsTooltipOverlay.prayerFromLabel("Rigour"));
		assertEquals(Prayer.RIGOUR, DpsTooltipOverlay.prayerFromLabel("<col=ff981f>Rigour</col>"));
		assertEquals(Prayer.RIGOUR, DpsTooltipOverlay.prayerFromLabel("Level 74<br>Rigour<br>Increases ranged"));
		assertEquals(Prayer.PROTECT_FROM_MAGIC, DpsTooltipOverlay.prayerFromLabel("Protect from Magic"));
		assertNull(DpsTooltipOverlay.prayerFromLabel("Cancel"));
	}

	@Test
	public void weaponsAndFoodAreNotPotions()
	{
		assertFalse(PotionBoosts.affectsCombat("Twisted bow"));
		assertFalse(PotionBoosts.affectsCombat("Shark"));
		assertNull(DpsDelta.potion(ranged(), 99, 99, 99, 99, "Twisted bow"));
	}

	private static CombatInput ranged()
	{
		CombatInput in = new CombatInput();
		in.combatStyle = CombatStyle.RANGED;
		in.stance = AttackStance.RANGED_RAPID;
		in.rangedLevel = 99;
		in.rangedBonus = 100;
		in.rangedStrengthBonus = 80;
		in.weaponSpeed = 5;
		in.npcDefence = 50;
		in.npcStandard = 0;
		in.npcMagic = 1;
		return in;
	}
}

